style.css:
@-moz-document domain("roblox.com") {
html {
        background: #000 !important;
    }

    #app,
    #app-container,
    .content {
        background-color: transparent !important;
    }

    #app::before {
        content: "";
        position: fixed;
        inset: 0;
        background-image: url(https://i.pinimg.com/1200x/19/9a/df/199adfa172abc5be3504e84f928a9335.jpg);
        background-repeat: no-repeat;
        background-position: right center;
        background-size: auto 100vh;
        pointer-events: none;
        z-index: -1;
    }
}
